using Microsoft.AspNetCore.Mvc;
using StarCorp.FlightBooking.Core.DTOs;
using StarCorp.FlightBooking.Core.Enums;
using StarCorp.FlightBooking.Core.Interfaces;
using StarCorp.FlightBooking.Core.Models;

namespace StarCorp.FlightBooking.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class BookingsController : ControllerBase
{
    private readonly IBookingRepository _bookingRepo;
        private readonly IFlightRepository _flightRepo;
            private readonly ICustomerRepository _customerRepo;
                private readonly IPricingService _pricingService;
                    private readonly ICancellationService _cancellationService;

                        public BookingsController(
                                IBookingRepository bookingRepo,
                                        IFlightRepository flightRepo,
                                                ICustomerRepository customerRepo,
                                                        IPricingService pricingService,
                                                                ICancellationService cancellationService)
                                                                    {
                                                                            _bookingRepo = bookingRepo;
                                                                                    _flightRepo = flightRepo;
                                                                                            _customerRepo = customerRepo;
                                                                                                    _pricingService = pricingService;
                                                                                                            _cancellationService = cancellationService;
                                                                                                                }
                                                                                                                
                                                                                                                    /// <summary>Cria uma nova reserva (sem pagamento).</summary>
                                                                                                                        [HttpPost]
                                                                                                                            public async Task<IActionResult> Create([FromBody] CreateBookingRequest request)
                                                                                                                                {
                                                                                                                                        var flight = await _flightRepo.GetByIdAsync(request.FlightId);
                                                                                                                                                if (flight == null)
                                                                                                                                                            return NotFound("Voo não encontrado.");
                                                                                                                                                            
                                                                                                                                                                    if (flight.Status != "Scheduled")
                                                                                                                                                                                return Conflict("Voo não está disponível para reserva.");
                                                                                                                                                                                
                                                                                                                                                                                        if (!flight.HasAvailableSeats(request.FareClass, request.Passengers.Count))
                                                                                                                                                                                                    return Conflict("Assentos insuficientes para a classe e quantidade de passageiros solicitada.");
                                                                                                                                                                                                    
                                                                                                                                                                                                            var customer = await _customerRepo.GetByCPFAsync(request.Customer.CPF)
                                                                                                                                                                                                                        ?? await _customerRepo.CreateAsync(new Customer
                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                    Name = request.Customer.Name,
                                                                                                                                                                                                                                                                    Email = request.Customer.Email,
                                                                                                                                                                                                                                                                                    CPF = request.Customer.CPF,
                                                                                                                                                                                                                                                                                                    Phone = request.Customer.Phone
                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                        if (!customer.IsActive)
                                                                                                                                                                                                                                                                                                                                    return UnprocessableEntity("Cliente está inativo e não pode realizar reservas.");
                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                            var booking = new Booking
                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                BookingCode = GenerateBookingCode(),
                                                                                                                                                                                                                                                                                                                                                                            CustomerId = customer.Id,
                                                                                                                                                                                                                                                                                                                                                                                        FlightId = request.FlightId,
                                                                                                                                                                                                                                                                                                                                                                                                    FareClass = request.FareClass,
                                                                                                                                                                                                                                                                                                                                                                                                                Status = BookingStatus.Pending,
                                                                                                                                                                                                                                                                                                                                                                                                                            TotalAmount = 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                        Passengers = request.Passengers.Select(p => new Passenger
                                                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Name = p.Name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    CPF = p.CPF,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    BirthDate = p.BirthDate
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }).ToList()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var created = await _bookingRepo.CreateAsync(booking);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await _flightRepo.UpdateSeatsAsync(request.FlightId, request.FareClass, request.Passengers.Count);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /// <summary>Retorna uma reserva pelo ID.</summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [HttpGet("{id:int}")]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                public async Task<IActionResult> GetById(int id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var booking = await _bookingRepo.GetByIdAsync(id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return booking == null ? NotFound() : Ok(booking);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /// <summary>Retorna uma reserva pelo código de reserva.</summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                [HttpGet("code/{code}")]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    public async Task<IActionResult> GetByCode(string code)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var booking = await _bookingRepo.GetByCodeAsync(code);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return booking == null ? NotFound() : Ok(booking);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /// <summary>Lista todas as reservas de um cliente.</summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    [HttpGet("customer/{customerId:int}")]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        public async Task<IActionResult> GetByCustomer(int customerId)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var bookings = await _bookingRepo.GetByCustomerIdAsync(customerId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return Ok(bookings);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /// <summary>Processa o pagamento de uma reserva pendente.</summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        [HttpPost("{id:int}/payment")]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            public async Task<IActionResult> ProcessPayment(int id, [FromBody] ProcessPaymentRequest request)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var booking = await _bookingRepo.GetByIdAsync(id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (booking == null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return NotFound("Reserva não encontrada.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (booking.Status != BookingStatus.Pending)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return Conflict("Apenas reservas com status Pendente podem ser pagas.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (booking.Payment != null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Conflict("Esta reserva já possui um pagamento registrado.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var flight = await _flightRepo.GetByIdAsync(booking.FlightId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (flight == null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return NotFound("Voo da reserva não encontrado.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var passengerCount = booking.Passengers?.Count ?? 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var price = _pricingService.CalculatePrice(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            flight.BasePriceEconomy,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        booking.FareClass,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    passengerCount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                request.PaymentMethod);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var payment = new Payment
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            BookingId = booking.Id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Method = request.PaymentMethod,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Amount = price.TotalAmount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Status = "Confirmed",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            PaidAt = DateTime.UtcNow,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        TransactionId = Guid.NewGuid().ToString("N").ToUpper()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await _bookingRepo.AddPaymentAsync(payment);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await _bookingRepo.UpdateTotalAmountAsync(booking.Id, price.TotalAmount);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await _bookingRepo.UpdateStatusAsync(booking.Id, BookingStatus.Confirmed);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return Ok(new
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    BookingId = booking.Id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                BookingCode = booking.BookingCode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Payment = payment,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        PriceBreakdown = price
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /// <summary>Cancela uma reserva e calcula o reembolso.</summary>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            [HttpPost("{id:int}/cancel")]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                public async Task<IActionResult> Cancel(int id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var booking = await _bookingRepo.GetByIdAsync(id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (booking == null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return NotFound();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var refund = _cancellationService.CalculateRefund(booking, DateTime.UtcNow);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!refund.IsSuccess)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return UnprocessableEntity(new { refund.Reason });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await _bookingRepo.UpdateStatusAsync(id, BookingStatus.Cancelled);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Devolve assentos ao voo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await _flightRepo.UpdateSeatsAsync(booking.FlightId, booking.FareClass, -(booking.Passengers?.Count ?? 0));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return Ok(new
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                BookingId = id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            BookingCode = booking.BookingCode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        refund.RefundAmount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    refund.RefundPercentage,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                refund.Reason
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                private static string GenerateBookingCode() =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Guid.NewGuid().ToString("N").ToUpper();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
